\label{lem:gaussian-average}
Let $f\in L^1(\mathbb{T}^{d_2})$ and extend it $\mathbb{Z}^{d_2}$-periodically onto $\mathbb{R}^{d_2}$.  Then,
we have
\begin{equation}
 \lim_{\varepsilon\to 0}
 \varepsilon^{d_2/2}\int_{\mathbb{R}^{d_2}}f(x_2)L_\varepsilon (x_2)\, dx_2
 =\int_{\mathbb{T}^{d_2}}f(x_2)\, dx_2.
 \label{eq:gaussian-average}
\end{equation}



\noindent
Moreover, given $0<r<\infty$ and $F\in L^r(\mathbb{R}^{d_1}\times\mathbb{T}^{d_2})$, we have
\begin{equation}
 \lim_{\varepsilon\to 0}
 \varepsilon^{d_2/(2r)}
 \|F(x_1, x_2)L_{\varepsilon/r}(x_2)\|_{L^r(\mathbb{R}^{d_1}\times\mathbb{R}^{d_2})}
 =\|F\|_{L^r(\mathbb{R}^{d_1}\times\mathbb{T}^{d_2})},
 \label{eq:norm-average}
\end{equation}

\noindent
where $F$ on the left-hand side
is the periodic extension
\textup{(}in the second variable $x_2$\textup{)}
of $F$ onto $\mathbb{R}^{d_1}\times\mathbb{R}^{d_2}$

\label{lem:resonance}
Let $m\in\mathbb N$ and $\alpha_0, \alpha_1,\ldots, \alpha_m>0$ such that
\(
\displaystyle\sum_{j=0}^m \alpha_j=1.
\)
For $x_2\in\mathbb{R}^{d_2}$ and $\boldsymbol y\in\mathbb{R}^{md_2}$, define
\begin{align}
 \Gamma_{\varepsilon, x_2}(\boldsymbol y)
 =\varepsilon^{d_2/2}G_{\varepsilon, \alpha_0}
(x_2- y_{1\cdots m})
\prod_{j=1}^m G_{\varepsilon, \alpha_j}(y_j).
 \label{G2}
\end{align}


\noindent
Then, we have
\begin{equation}
 \int_{\mathbb{R}^{md_2}}\Gamma_{\varepsilon, x_2}(\boldsymbol y)\, d\boldsymbol y
 =G_{\varepsilon,  \alpha_{0\cdots m}}(x_2)=L_{1/\varepsilon}(x_2).
\label{G2a}
\end{equation}


\noindent
In \eqref{G2} and \eqref{G2a}, we used the shorthand notation \eqref{sum1}
and \eqref{sum2}.

\label{LEM:multitrans1}
Let $m\in\mathbb N$ and $d, d_1,d_2\in\mathbb{N}$ with $d=d_1+d_2$.
Given a bounded and continuous function $\sigma: \mathbb{R}^{md_1}\times\mathbb{R}^{md_2}\to\mathbb C$,
let $T_\sigma$ and $S_\sigma$ be as in \eqref{T1} and \eqref{T2}, respectively.
If $K_{T_\sigma} \in L^1(\mathbb{R}^{md_1}\times\mathbb{R}^{md_2})$, then $K_{S_\sigma}\in
L^1(\mathbb{R}^{md_1}\times\mathbb{T}^{md_2})$
with the  bound\textup{:}
\begin{align}
\|K_{S_\sigma}\|_{L^1(\mathbb{R}^{md_1}\times\mathbb{T}^{md_2})}
\le
\|K_{T_\sigma}\|_{L^1(\mathbb{R}^{md})} < \infty.
\label{multitrans1}
\end{align}

\noindent
In particular,
 given any  \(1\leq p, p_1,\ldots, p_m<\infty\)
satisfying
\begin{align}
\displaystyle\frac{1}{p}=\displaystyle\sum_{j=1}^m \displaystyle\frac{1}{p_j},
\label{T3}
\end{align}
the operator  $S_\sigma$ is bounded from $L^{p_1}(\mathbb{R}^{d_1}\times\mathbb{T}^{d_2})\times\cdots \times L^{p_m}(\mathbb{R}^{d_1}\times\mathbb{T}^{d_2})$ to $L^p(\mathbb{R}^{d_1}\times\mathbb{T}^{d_2})$
with the following operator bound\textup{:}
\begin{align}
\| S_\sigma\|_{L^{p_1}\times\cdots\times L^{p_m}\to L^{p}}
\le
\|K_{T_\sigma}\|_{L^1(\mathbb{R}^{md})}.
\label{multitrans2}
\end{align}

Let $K_{T_\sigma}\in L^1(\mathbb R^{md_1}\times
\mathbb R^{md_2})$ be the convolution kernel of $T_\sigma$. Define its
periodization in the second variable by
\begin{align*}
    \widetilde K(\boldsymbol x,\boldsymbol y)
    = \sum_{\boldsymbol k\in\mathbb Z^{md_2}}K_{T_\sigma}(\boldsymbol x,\boldsymbol y+\boldsymbol k),
    \qquad
    (\boldsymbol x,\boldsymbol y)\in\mathbb R^{md_1}\times\mathbb T^{md_2}.
\end{align*}

\noindent
By the Fubini--Tonelli theorem, the sum converges absolutely for almost
every $(\boldsymbol x,\boldsymbol  y)$, and $\widetilde K\in
L^1(\mathbb R^{md_1}\times\mathbb T^{md_2})$. Moreover,
we have
\begin{align}
\begin{split}
    \|\widetilde K\|_{L^1(\mathbb R^{md_1}\times\mathbb T^{md_2})}
    &\le
    \int_{\mathbb R^{md_1}}\int_{\mathbb T^{md_2}}
    \sum_{k\in\mathbb Z^{md_2}}
    |K_{T_\sigma}(\boldsymbol x,\boldsymbol y+\boldsymbol k)|\,d\boldsymbol yd\boldsymbol x \\
    &=
    \int_{\mathbb R^{md_1}}\int_{\mathbb R^{md_2}}
    |K_{T_\sigma}(\boldsymbol x,\boldsymbol y)|\,d\boldsymbol yd\boldsymbol x \\
    &=
    \|K_{T_\sigma}\|_{L^1(\mathbb R^{md})}.
\end{split}
\label{Z1}
\end{align}

We claim that $\widetilde K=K_{S_\sigma}$. Indeed, for every
$n\in\mathbb Z^{md_2}$, the $\boldsymbol n$th Fourier coefficient of
$\widetilde K$ in the periodic variable is given, for almost every
$\boldsymbol  x\in\mathbb R^{md_1}$, by
\begin{align*}
    \int_{\mathbb T^{md_2}}\widetilde K(\boldsymbol x,\boldsymbol y)e^{-2\pi i \boldsymbol n\cdot \boldsymbol y}\,d\boldsymbol y
    &=
    \int_{\mathbb R^{md_2}}
    K_{T_\sigma}(\boldsymbol x,\boldsymbol y)e^{-2\pi i \boldsymbol n\cdot \boldsymbol y}\,d\boldsymbol y\\
    &=
    \mathcal F_{\mathbb R^{md_2}}^{(2)}
    (K_{T_\sigma})(\boldsymbol x,\boldsymbol n).
\end{align*}
Taking the Fourier transform also in
$\boldsymbol x\in\mathbb R^{md_1}$, we obtain
\begin{align*}
    \mathcal F_{\mathbb R^{md_1}}
    \left[
    \int_{\mathbb T^{md_2}}
    \widetilde K(\,\cdot\,,\boldsymbol y)e^{-2\pi i \boldsymbol n\cdot \boldsymbol y}\,d\boldsymbol y
    \right](\boldsymbol \xi)
    =
    \sigma(\boldsymbol \xi,\boldsymbol n).
\end{align*}


\noindent
Thus,  $\widetilde K$ has Fourier transform $\sigma(\boldsymbol \xi,\boldsymbol n)$ on
$\mathbb R^{md_1}\times\mathbb Z^{md_2}$ and
hence
$\widetilde K=K_{S_\sigma}$.
Therefore,
\eqref{multitrans1} follows from \eqref{Z1}.
The bound \eqref{multitrans2} then follows from \eqref{multitrans1} and \eqref{T0}.

Let
\begin{align}
A=\|T_\sigma\|_{L^{p_1}(\mathbb{R}^d)\times\cdots\times L^{p_m}(\mathbb{R}^d)\to L^p(\mathbb{R}^d)}, \quad \alpha_0=\frac{1}{p'},\quad \text{and}\quad \alpha_j=\frac{1}{p_j}
\label{T4a}
\end{align}


\noindent
for $j = 1, \dots, m$.
Then, \eqref{T3} reduces to
\begin{equation}
 \alpha_0+\alpha_1+\cdots+\alpha_m=1.
 \label{T4}
\end{equation}
Next, we define a dense class of elementary functions on $\mathbb R^{d_1}\times\mathbb{T}^{d_2}$ as follows;
 we say that $F$ is an elementary function (defined on $\mathbb R^{d_1}\times\mathbb{T}^{d_2}$) if there exists
a finite set $\Lambda \subset \mathbb{Z}^{d_2}$  and a collection  $\{f_n\}_{n\in\Lambda } \subset \mathcal{S}(\mathbb{R}^{d_1})$ such that
\begin{equation*}
 F(x_1, x_2)=\sum_{n\in \Lambda }f_n(x_1)e^{2\pi i n\cdot x_2},
 \quad (x_1, x_2) \in\mathbb{R}^{d_1}\times \mathbb{T}^{d_2}.

\end{equation*}
We denote by $\mathcal E$ the collection of these elementary functions, namely
\begin{align}
\mathcal E
=\bigg\{F=\sum_{n\in\Lambda}f_n\otimes e_n^{(2)},\,\, \Lambda\subset\mathbb{Z}^{d_2}\,\,\text{finite},\,\,f_n\in\mathcal S(\mathbb{R}^{d_1})\bigg\},
\label{T5a}
\end{align}


\noindent
where we wrote $e_n^{(2)}(x_2)=e^{2\pi in\cdot x_2},\, x_2\in\mathbb{T}^{d_2}.$  By the density of Schwartz functions and trigonometric polynomials, it follows that $\mathcal E$ is dense in $L^r(\mathbb{R}^{d_1}\times\mathbb{T}^{d_2})$, $0<r<\infty$.
In the following,  we often view a function on $\mathbb{R}^{d_1}\times\mathbb{T}^{d_2}$ as a function on $\mathbb{R}^{d_1}\times\mathbb{R}^{d_2}$ which is periodic in $x_2\in\mathbb{R}^{d_2}$.

For $j = 0, 1, \dots, m$,
let $F_j\in\mathcal E$.
Namely, there exists a finite set $\Lambda_j \subset \mathbb{Z}^{d_2}$
 and $f_{j, n_j}\in\mathcal{S}(\mathbb{R}^{d_1})$ such that
\begin{equation}
 F_j=\sum_{n_j\in\Lambda_j}f_{j,n_j}\otimes e_{n_j}^{(2)}.
 \label{T6}
\end{equation}

\noindent
Then,
for $\varepsilon>0$, define the Schwartz functions $F_{j, \varepsilon}$ on $\mathbb{R}^{d}$ by
\begin{align}
 F_{j,\varepsilon}(x_1, x_2)=F_j(x_1, x_2)L_{\varepsilon\alpha_j}(x_2),
\label{T6a}
\end{align}



\noindent
where $L_{\varepsilon\alpha_j}$ is as in \eqref{L1}.
Note that by Lemma~\ref{lem:gaussian-average}, we have
\begin{align}
\begin{split}
\lim_{\varepsilon\to 0}
 \varepsilon^{d_2/(2p')}
 \|F_{0, \varepsilon}\|_{L^{p'}(\mathbb{R}^{d})}
 &=\|F_0\|_{L^{p'}(\mathbb{R}^{d_1}\times\mathbb{T}^{d_2})}, \\
\lim_{\varepsilon\to 0}
 \varepsilon^{d_2/(2p_j)}
 \|F_{j, \varepsilon}\|_{L^{p_j}(\mathbb{R}^{d})}
 &=\|F_j\|_{L^{p_j}(\mathbb{R}^{d_1}\times\mathbb{T}^{d_2})}, \quad j = 1, \dots, m.
\end{split}
 \label{T7}
\end{align}

\medskip

\noindent
$\bullet$~\textbf{Step 1:}
Given $\varepsilon > 0$, let
\begin{align}
I_\varepsilon=\varepsilon^{d_2/2}\int_{\mathbb{R}^d}
 T_\sigma(F_{1,\varepsilon},\ldots,F_{m,\varepsilon})(x)
 \overline{F_{0, \varepsilon}(x)}\, dx
\label{T7a}
\end{align}



\noindent
for $F_{j, \varepsilon}$, $j = 0, 1, \dots, m$,  as in \eqref{T6a}.
We claim that
\begin{equation}
 \lim_{\varepsilon\to 0}I_\varepsilon
 =\int_{\mathbb{R}^{d_1}\times\mathbb{T}^{d_2}}
 S_\sigma(F_1,\ldots,F_m)(x_1, x_2)\overline{F_0(x_1, x_2)}
 \,dx_1dx_2.
 \label{T8}
\end{equation}

From \eqref{T6a} and \eqref{G1}, we have
\begin{equation}
 \widehat F_{j,\varepsilon}(\xi,\eta)
 =\sum_{n_j\in \Lambda_j}\widehat f_{j,n_j}(\xi)G_{\varepsilon, \alpha_j}(\eta-n_j).
\label{T9}
\end{equation}


\noindent
For $\boldsymbol\xi \in \mathbb{R}^{md_1}$,   $\boldsymbol n = (n_1, \dots, n_m) \in \mathbb{Z}^{md_2}$,
and  $n_0 \in \mathbb{Z}^{d_2}$,
define  $J_\varepsilon(\boldsymbol\xi,\boldsymbol n, n_0)$ by setting
\begin{equation}
\label{T10}
 J_\varepsilon(\boldsymbol\xi,\boldsymbol n, n_0)=\int_{\mathbb{R}^{md_2}}
 \sigma(\boldsymbol\xi, \boldsymbol n+\boldsymbol y)
 \Gamma_{\varepsilon,\,n_{1\cdots m}-n_0}(\boldsymbol y)
 \, d\boldsymbol y,
\end{equation}


\noindent
where $ \Gamma_{\varepsilon,\,n_{1\cdots m}-n_0}$ is as in \eqref{G2}
with the notation \eqref{sum1}.
Noting that
 the sums in \eqref{T6}, defining the elementary functions $F_j$ are finite,
 it follows from  Parseval's identity,  the definition \eqref{T1} of $T_\sigma$,
\eqref{T9},  \eqref{G1a},
 \eqref{T4}  and a change of variables $y_j=\eta_j-n_j$ with \eqref{T10}
 (see also \eqref{G2}) that
\begin{align}
 I_\varepsilon
 &=\sum_{\substack{n_j\in \Lambda_j\\ j = 0, 1, \dots, m}}
   \int_{\mathbb{R}^{md_1}}
   J_\varepsilon(\boldsymbol\xi,\boldsymbol n, n_0)
\prod_{j=1}^m\widehat f_{j,n_j}(\xi_j)\cdot
    \overline{\widehat f_{0, n_0} (\xi_{1\cdots m})}
   \,d\boldsymbol\xi.
\label{T11}
\end{align}



By applying
 Lemma~\ref{lem:resonance} to \eqref{T10}, we are led to consider two cases.
In the non-resonant case: $n_0 \ne n_{1\cdots m},$ we have
\begin{align}
|J_\varepsilon(\boldsymbol\xi,\boldsymbol n, n_0)|
 \leq\|\sigma\|_{L^\infty(\mathbb{R}^{md})}L_{1/\varepsilon}(n_{1\cdots m}- n_0)
 \longrightarrow 0,
\label{T12}
\end{align}


\noindent
as $\varepsilon\to 0$.
In the resonant case: $n_0 = n_{1\cdots m} $,
it follows from the boundedness and continuity of $\sigma$ with \eqref{G4}
that
\begin{align}
\lim_{\varepsilon\to 0}J_\varepsilon(\boldsymbol\xi,\boldsymbol n, n_0)=
\sigma (\boldsymbol\xi, \boldsymbol n).
\label{T13}
\end{align}

\noindent
Moreover, in both cases, we have \(|J_\varepsilon|\leq\|\sigma\|_{L^\infty(\mathbb{R}^{md})}\). For every fixed finite tuple of indices, the remaining function of $\boldsymbol\xi$ in \eqref{T11} is integrable as
\[\int_{\mathbb{R}^{md_1}}
 \prod_{j=1}^m |\widehat f_{j,n_j}(\xi_j)|
\cdot |\widehat f_{0, n_0}(\xi_{1\cdots m})|d\boldsymbol\xi
 \leq
 \|\widehat f_{0, n_0}\|_{L^\infty(\mathbb{R}^{d_1})}
 \prod_{j=1}^m\|\widehat f_{j,n_j}\|_{L^1(\mathbb{R}^{d_1})}<\infty.
\]

\noindent
By applying the
 Lebesgue dominated convergence
 to $I_\varepsilon$ in  \eqref{T11}
 with \eqref{T12} and \eqref{T13},
 we obtain
\begin{align*}
 \lim_{\varepsilon\to 0}I_\varepsilon =
 \sum_{\substack{n_j\in \Lambda_j\\ j = 0, 1, \dots, m\\ n_0 = n_{1\cdots m}}}
    \int_{\mathbb{R}^{md_1}}
\sigma (\boldsymbol\xi, \boldsymbol n).
\prod_{j=1}^m\widehat f_{j,n_j}(\xi_j)\cdot
    \overline{\widehat f_{0, n_0} (\xi_{1\cdots m})}
   \,d\boldsymbol\xi.
\end{align*}

\noindent
In view of \eqref{T2} and \eqref{T6}
with Parseval's identity,
this  is exactly
 the Fourier expansion of the right-hand side of~\eqref{T8}, proving our claim \eqref{T8}.

\medskip

\noindent
$\bullet$~\textbf{Step 2:} We now prove the bound \eqref{eq:mainbound} via duality.
By applying
H\"older's inequality and  the boundedness of $T_\sigma$
to $I_\varepsilon$ in
\eqref{T7a}
with  \(1/p'+\sum_{j=1}^m 1/p_j=1\), we have
\begin{equation}
\begin{split}
 |I_\varepsilon|
&  \leq A\,\varepsilon^{d_2/2}
 \|F_{0, \varepsilon}\|_{L^{p'}(\mathbb{R}^d)}
 \prod_{j=1}^m\|F_{j,\varepsilon}\|_{L^{p_j}(\mathbb{R}^d)}
\\
&  =A
 \left(\varepsilon^{d_2/(2p')}
       \|F_{0, \varepsilon}\|_{L^{p'}(\mathbb{R}^d)}\right)
 \prod_{j=1}^m
 \left(\varepsilon^{d_2/(2p_j)}
       \|F_{j,\varepsilon}\|_{L^{p_j}(\mathbb{R}^d)}\right),
\end{split}
 \label{eq:Ieps-bound}
\end{equation}

\noindent
where $A$ is as in \eqref{T4a}.
Letting $\varepsilon\to 0$ in \eqref{eq:Ieps-bound} together with \eqref{T8} and \eqref{T7},
we obtain
\begin{equation}
\label{eq:final}
\begin{split}
& \bigg|\int_{\mathbb{R}^{d_1}\times\mathbb{T}^{d_2}}
 S_\sigma(F_1,\ldots,F_m)(x_1, x_2)\overline{F_0(x_1, x_2)}\,dx_1dx_2\bigg|\\
& \hphantom{XXXXXXXXXX}
  \leq A
 \|F_0\|_{L^{p'}(\mathbb{R}^{d_1}\times\mathbb{T}^{d_2})}
 \prod_{j=1}^m\|F_j\|_{L^{p_j}(\mathbb{R}^{d_1}\times\mathbb{T}^{d_2})},
\end{split}
\end{equation}
for any elementary functions $F_j\in\mathcal E$,
$j = 0, 1, \dots, m$.
Therefore, the bound \eqref{eq:mainbound} follows from~\eqref{eq:final}
and the density of $\mathcal E$ in $L^{p_j}(\mathbb{R}^{d_1}\times\mathbb{T}^{d_2})$.

In  the proof of Proposition~\ref{LEM:multitrans2},
 we  used Gaussian localization and the $(L^p, L^{p'})$-duality.

For a weak-type estimate,
 this duality is less natural,
 and thus  we adapt  the cutoff argument from the proof of  \cite[Theorem 4]{FS}.

Let
\begin{align}
B=\|T_\sigma\|_{L^{p_1}(\mathbb{R}^d)\times\cdots\times L^{p_m}(\mathbb{R}^d)
 \to L^{p,\infty}(\mathbb{R}^d)}.
\label{S2}
\end{align}


\noindent
Namely,
$B$ is the smallest constant such that
\begin{equation}
\label{eq:weakTbound}
 \bigl\lvert
 \{x\in\mathbb{R}^d:
 \lvert T_\sigma(f_1,\ldots, f_m)(x)\rvert>\lambda\}
 \bigr\rvert
 \leq
 \left(
 \frac{B\prod_{j=1}^m\|f_j\|_{L^{p_j}(\mathbb{R}^d)}}{\lambda}
 \right)^p
\end{equation}

\noindent
for any \(\lambda>0\).
As in the proof of Proposition~\ref{LEM:multitrans2}, it suffices to prove our estimates for the class $\mathcal E$ of elementary functions
defined in \eqref{T5a}.
In the following, we fix
  $F_j\in\mathcal E$,  $j = 1, \dots, m$,  as in \eqref{T6}.


Let $Q=[-\frac{1}{2}, \frac{1}{2}]^{d_2}$, $Q_K=
 \left[-\frac{1}{2}-\frac{1}{K},\frac{1}{2}+\frac{1}{K}\right]^{d_2}$ for a fixed \(K\in\mathbb{N}\), and choose \(\Psi\in C_c^\infty(\mathbb{R}^{d_2}; [0, 1])\) such that
\begin{equation*}
 \Psi=1 \text{ on } Q
 \qquad \text{and}\qquad
 \operatorname{supp}\Psi\subset Q_K.
\end{equation*}
Following \cite[(3.1)]{FS}, for $N\in\mathbb{N}$ define
the error term $ E_N (F_1,\ldots, F_m)$ by setting
\begin{equation}
\label{eq:EN}
\begin{split}
 E_N (F_1,\ldots, F_m)(x_1, x_2)
 & =\Psi_N(x_2)^m S_\sigma(F_1,\ldots, F_m)(x_1, x_2)\\
 & \quad -T_\sigma(F_{1,N},\ldots, F_{m,N})(x_1, x_2),
\end{split}
\end{equation}
where
\begin{align}
 \Psi_N(x_2)=\Psi(x_2/N)
 \quad
 \text{and}\quad
 F_{j,N}(x_1,x_2)=F_j(x_1,x_2)\Psi_N(x_2).
\label{S4}
\end{align}

\medskip

\noindent
$\bullet$~\textbf{Step 1:} We first show  that the following uniform approximation holds:
\begin{equation}
\label{eq:ENuniform}
 \|E_N (F_1,\ldots, F_m)\|_{L^\infty(\mathbb{R}^d)}\longrightarrow0
 \quad\text{as }N\to\infty.
\end{equation}



From \eqref{S4} with \eqref{T6}, we have
\[
 \widehat F_{j,N}(\xi_j,\eta_j)
 =
 \sum_{n_j\in\Lambda_j}
 \widehat f_{j, n_j}(\xi_j)\,
 N^{d_2}\widehat\Psi\bigl(N(\eta_j-n_j)\bigr)
\]

\noindent
Then, by a change of variables  $u_j=N(\eta_j-n_j)$, we obtain
\begin{align}
\begin{split}
&T_\sigma(F_{1,N},\ldots,F_{m,N})(x_1,x_2)
\\
&\quad =
\sum_{\substack{n_j\in\Lambda_j\\  j = 1, \dots, m}}
\int_{\mathbb{R}^{md_1}}\int_{\mathbb{R}^{md_2}}
 \sigma\left(
 \boldsymbol\xi,
 \boldsymbol n+\boldsymbol u/N
 \right)
 \prod_{j=1}^m
 \widehat f_{j,n_j}(\xi_j)\widehat\Psi(u_j)
\\
&\hspace{2.8cm}\times
 e^{2\pi i x_1\cdot\sum_{j=1}^m\xi_j}
 e^{2\pi i x_2\cdot\sum_{j=1}^m n_j}
 e^{2\pi i (x_2/N)\cdot\sum_{j=1}^m u_j}
 \,d\boldsymbol u\,d\boldsymbol\xi ,
\end{split}
\label{S5}
\end{align}

\noindent
where $\boldsymbol u = (u_1, \dots, u_m)$.
On the other hand, from \eqref{T2} with \eqref{S4},
 we have
\begin{align}
\begin{split}
&\Psi_N(x_2)^mS_\sigma(F_{1},\ldots,F_{m})(x_1,x_2)
\\
&=
\sum_{\substack{n_j\in\Lambda_j\\ j = 1, \dots, m}}
\int_{\mathbb{R}^{md_1}}\int_{\mathbb{R}^{md_2}}
 \sigma\left(
 \boldsymbol\xi,
 \boldsymbol n
 \right)
 \prod_{j=1}^m
 \widehat f_{j,n_j}(\xi_j)\widehat\Psi(u_j)
\\
&\hspace{2.8cm}\times
 e^{2\pi i x_1\cdot\sum_{j=1}^m\xi_j}
 e^{2\pi i x_2\cdot\sum_{j=1}^m n_j}
 e^{2\pi i (x_2/N)\cdot\sum_{j=1}^m u_j}
 \,d\boldsymbol u\,d\boldsymbol\xi.
\\
\end{split}
\label{S6}
\end{align}


\noindent
Thus, from \eqref{eq:EN}, \eqref{S5}, and \eqref{S6}, we have
\begin{align}
\begin{split}
&  \lvert E_N(F_1,\ldots, F_m)(x_1,x_2)\rvert\\
 &\ \  \le
 \sum_{\substack{n_j\in\Lambda_j\\ j = 1, \dots, m}}
 \int_{\mathbb{R}^{md_1}}\int_{\mathbb{R}^{md_2}}
 \left|
 \sigma(\boldsymbol\xi,\boldsymbol n)
 -
 \sigma\left(
 \boldsymbol\xi,\boldsymbol n+\boldsymbol u/N
 \right)
 \right|
 \prod_{j=1}^m
|\widehat f_{j,n_j}(\xi_j)|
|\widehat\Psi(u_j)|
 \,d\boldsymbol u\,d\boldsymbol\xi.
\end{split}
\label{S7}
\end{align}







For every fixed \((\boldsymbol\xi,\boldsymbol n,\boldsymbol u)\), the continuity
of \(\sigma\) implies that
\begin{align}
2\|\sigma\|_{L^\infty(\mathbb{R}^{md})}\geq \left|
 \sigma(\boldsymbol\xi,\boldsymbol n)
 -
 \sigma\left(
 \boldsymbol\xi,\boldsymbol n+\boldsymbol u/N
 \right)
 \right|\longrightarrow 0,
\label{S8}
\end{align}

\noindent
as $N \to \infty$.
By noting that
the sums over the \(n_j\)'s in \eqref{S8} are finite
and recalling that
\(\widehat f_{j,n_j}\in L^1 \left(\mathbb{R}^{d_1}\right)\), and
\(\widehat\Psi\in L^1\left(\mathbb{R}^{d_2}\right)\),
we see that
the right-hand side of
\eqref{S7} is bounded by an integrable function independent of
$N$, $x_1$, and $x_2$.  Therefore,
the convergence
\eqref{eq:ENuniform}
follows from \eqref{S8} and the Lebesgue dominated convergence theorem.

\medskip




\noindent
$\bullet$~\textbf{Step 2:}
Since  \(\Psi_N=1\) on \(NQ\), the relation \eqref{eq:EN} simplifies to
\begin{align}
S_\sigma(F_1,\ldots,F_m)(x_1, x_2)
 =
 T_\sigma(F_{1,N},\ldots,F_{m,N})(x_1, x_2)+E_N(F_1,\ldots, F_m)(x_1, x_2)
\label{S9}
\end{align}


\noindent
for $x_1\in\mathbb{R}^{d_1}$ and $x_2\in NQ$.


Fix $\lambda>0$
and define $\Omega_\lambda$ by
\begin{align}
\Omega_\lambda=
 \big\{
 (x_1, x_2)\in\mathbb{R}^{d_1}\times Q:
 \lvert S_\sigma(F_1,\ldots,F_m)(x_1,x_2)\rvert>\lambda
 \big\}.
\label{S9a}
\end{align}


\noindent
Since $S_\sigma(F_1,\ldots,F_m)$ is periodic in the second variable,
we have
\begin{align}
\lvert \Omega_\lambda\rvert=N^{-d_2}\bigl\lvert\bigl\{(x_1,x_2)\in\mathbb{R}^{d_1}\times NQ:\lvert S_\sigma(F_1,\ldots,F_m)(x_1,x_2)\rvert>\lambda\bigr\}\bigr\rvert.
\label{S10}
\end{align}



Given small  $\varepsilon\in (0, \lambda)$,
it follows from \eqref{eq:ENuniform} that
there exists $N_\varepsilon \in \mathbb{N}$ such that
\begin{align}
 \|E_{N_\varepsilon}(F_1,\ldots, F_m)\|_{L^\infty(\mathbb{R}^d)}<\varepsilon
 \label{S11}
\end{align}



\noindent
for  any $N \ge N_\varepsilon$.
Hence, from \eqref{S9} and \eqref{S11}
 we have
\begin{align}
\begin{split}
&\big\{
 (x_1,x_2)\in\mathbb{R}^{d_1}\times NQ:
 \lvert S_\sigma(F_1,\ldots,F_m)(x_1,x_2)\rvert>\lambda
 \big\}
\\
&\quad\subset
\big\{
 x\in\mathbb{R}^d:
 \lvert T_\sigma(F_{1,N},\ldots,F_{m,N})(x)\rvert
 >\lambda-\varepsilon
 \big\}
 \end{split}
\label{eq:inclusion}
\end{align}

\noindent
for any $N \ge N_\varepsilon$.

Therefore,
from  \eqref{S10}, \eqref{eq:inclusion},
and  \eqref{eq:weakTbound}, we obtain
\begin{equation}
\label{eq:norms-1stesti}
 \lvert\Omega_\lambda\rvert
 \le
 N^{-d_2}
 \left(
 \frac{
 B\prod_{j=1}^m\|F_{j,N}\|_{L^{p_j}(\mathbb{R}^d)}
 }{\lambda-\varepsilon}
 \right)^p
\end{equation}
for any $\varepsilon\in (0, \lambda)$ and $N \ge N_\varepsilon$.

\medskip

\noindent
$\bullet$~\textbf{Step 3:}
We now have a closer look at  the right-hand side of \eqref{eq:norms-1stesti}.
Recalling that
 $0\le\Psi_N\le1$ and \(\operatorname{supp}\Psi_N\subset NQ_K\),
 it follows from \eqref{S4} and the periodicity of $F_j$ in the second variable that
\begin{align*}
 \|F_{j,N}\|_{L^{p_j}(\mathbb{R}^d)}^{p_j}&\leq
 \int_{\mathbb{R}^{d_1}}\int_{NQ_K}
 \lvert F_j(x_1,x_2)\rvert^{p_j}\,dx_2\,dx_1\\
 &\leq N^{d_2}\bigl(1+2/K+2/N\bigr)^{d_2}\int_{\mathbb{R}^{d_1}}\int_{Q}
 \lvert F_j(x_1,x_2)\rvert^{p_j}\,dx_2\,dx_1.
\end{align*}

\noindent
Consequently, we have
\begin{equation}
\label{eq:cutoff-limsup}
 \limsup_{N\to\infty}
 N^{-d_2/p_j}
 \|F_{j,N}\|_{L^{p_j}(\mathbb{R}^d)}
 \leq
 \left(1+\frac{2}{K}\right)^{d_2/p_j}
 \|F_j\|_{L^{p_j}(\mathbb{R}^{d_1}\times\mathbb{T}^{d_2})}.
\end{equation}
Taking the product in \eqref{eq:cutoff-limsup} and using \eqref{T3},
we obtain
\begin{equation}
\label{eq:product-limsup}
 \limsup_{N\to\infty}
 N^{-d_2/p}
 \prod_{j=1}^m\|F_{j,N}\|_{L^{p_j}(\mathbb{R}^d)}
 \leq
 \left(1+\frac{2}{K}\right)^{d_2/p}
 \prod_{j=1}^m
 \|F_j\|_{L^{p_j}(\mathbb{R}^{d_1}\times\mathbb{T}^{d_2})}.
\end{equation}


\noindent
Hence,
from \eqref{eq:norms-1stesti} and \eqref{eq:product-limsup}, we obtain
\begin{equation}
 \lvert\Omega_\lambda\rvert
 \leq
 \left(1+\frac{2}{K}\right)^{d_2}
 \left(\frac{B\prod_{j=1}^m
 \|F_j\|_{L^{p_j}(\mathbb{R}^{d_1}\times\mathbb{T}^{d_2})}
 }{\lambda-\varepsilon}\right)^p.
\label{S12}
\end{equation}
Finally, by taking $K\to\infty$ and $\varepsilon\to 0$ in \eqref{S12},
we obtain
\begin{align}
\lvert\Omega_\lambda\rvert\leq\left(\frac{B\prod_{j=1}^m
 \|F_j\|_{L^{p_j}(\mathbb{R}^{d_1}\times\mathbb{T}^{d_2})}}{\lambda}\right)^p.
\label{S13}
\end{align}


\noindent
Therefore, the bound
\eqref{S1}
follows from
\eqref{S9a}, \eqref{S13}, and \eqref{S2}
with the density argument.
